var partner=function(n){return{showEditForm:function(t){n.ajax({method:"GET",url:"/partner/"+t}).done(function(t){t&&(n("#editModalContent").html(t),n("#editModal").modal("show"),n.validator.unobtrusive.parse("#editForm"))})},upsertResultHandle:function(t){n("#submitBtn").prop("disabled",!0);t.success?n("#successMsg").show():(n("#failedMsg").html(t.error),n("#failedMsg").show());setTimeout(function(){n("#submitBtn").prop("disabled",!1);t.success&&location.reload()},1e3)},showAddForm:function(){n.ajax({method:"GET",url:"/partner/add"}).done(function(t){t&&(n("#addModalContent").html(t),n("#addModal").modal("show"),n.validator.unobtrusive.parse("#addForm"))})}}}(jQuery);$(document).ready(function(){$("#partner-table").DataTable({order:[[0,"asc"]],lengthMenu:[100,200,500]})});